static void R200_GLMultiDrawArrays(GLcontext context, GLenum mode,
    const GLint *first, const GLsizei *count, GLsizei primcount)
{
    GLsizei index;
    (void)context;
    if (!first || !count || primcount <= 0)
        return;
    for (index = 0; index < primcount; ++index)
        if (count[index] > 0)
            Lib_glDrawArrays(mode, first[index], count[index]);
}

